// @generated by gen_api_layer:2026-08-24 (B3 graph query & backfill; Phase 4 2026-10-09 backfill 四腿退役——活投影 ConceptGraphView 实时增量兜底·消费面零真实调用)
package controllers

import net.imadz.common.auth.AuthAction

import javax.inject.{Inject, Singleton}
import net.imadz.metarch.application.projection.repository.{InviteTenantMemberDecisionViewRepository, OnboardTenantDecisionViewRepository}
import net.imadz.metarch.infrastructure.graph.GraphProjectionRepository
import play.api.libs.json.{JsArray, JsNull, JsObject, JsString, JsValue, Json}
import play.api.mvc._

import scala.collection.JavaConverters._
import scala.concurrent.{ExecutionContext, Future}
import scala.util.{Failure, Success, Try}

/**
 * GraphApiController（EP_Neo4j B3，2026-08-24）：
 *  - GET  /api/graph/stats                                各 label 节点计数（租户作用域）
 *  - GET  /api/graph/neighborhood/:conceptId?depth=N      概念邻域 N 跳遍历（租户作用域）
 *  - GET  /api/graph/export                               全图导出（租户作用域）
 *  （POST /api/graph/backfill 已退役 2026-10-09 Phase 4：四腿裸 SQL 查 DecisionView 旧表——腿 1 表已切
 *   Mongo 冻结＝读死数据；活投影 ConceptGraphView 实时增量兜底同写 kn: 空间；消费面零真实调用。）
 *
 * BUG-011（2026-08-26 Squad-B）：读端点租户隔离。可见性规则（S2-22 收权·2026-08-30 用户拍板已实施）：租户 token 一律不见元模型（Ws* 来自真源的板书投影，无 tenantId）——读面 strict 谓词 default-deny；业务节点（100% 带 tenantId）按可见租户集裁剪；元模型独立只读访问功能暂缓等真源稳定（见 BACKLOG S2-22）：
 * 节点/边带 tenantId 属性时仅当 ∈ 调用者可见租户集才返回；无 tenantId 的全局元数据节点
 * （Ws* 工作坊过程类）对所有人可见。JWT 仅含 {uid,tv,exp} 无租户声明，调用者租户归属由
 * 服务端解析：uid → OnboardTenantDecisionView（ownerUserId=uid 或 orgMemberIds 含 orgMemberIdOf(tenantId, uid)；
 * 邀请族视图为 evt=0 桩、名册可能不全，以 DecisionView 实际可查数据为准）。
 * 响应形状不变（仅减少行）。空可见租户集 ⇒ 默认拒绝（仅返回全局节点）。
 */
@Singleton
class GraphApiController @Inject() (
                                     authAction: AuthAction,
                                     tenantViews: OnboardTenantDecisionViewRepository,
                                     rosterViews: InviteTenantMemberDecisionViewRepository,
                                     val cc: ControllerComponents)(implicit ec: ExecutionContext)
  extends BaseController {

  override def controllerComponents: ControllerComponents = cc

  /** BUG-011：uid → 可见租户集（owner 或 member）；查无归属 = 空集 = 默认拒绝
    * BUG-028 读侧缓解（2026-09-07 批4）：成员可见性并集邀请族名册（joinedAt!=null && removedAt==null）——
    * S2-81 名册换源（2026-09-10）：onboard 视图成员判定＝orgMemberIds 含 orgMemberIdOf(tenantId, uid)
    * （原 List[Id].contains(String: uid) 恒 false——userId 永不在名册，可见性实际全靠邀请族名册并集）；
    * 名册判据与 AuthController.resolveTenantMembership 同源（登录能拿 tid ⇒ 图面可见同租户）。 */
  private def visibleTenantIds(userId: String): Future[Set[String]] =
    tenantViews.findAll().flatMap { all =>
      val ownedOrOnboardMember = all.filter(v => v.ownerUserId == userId || net.imadz.metarch.domain.entities.OrganizationMemberIds.isMemberOf(v.tenantId, userId, v.orgMemberIds)).map(_.tenantId).toSet
      rosterViews.findByUserId(userId).map { roster =>
        val joinedRoster = roster.filter(r => r.joinedAt.isDefined && r.removedAt.isEmpty).map(_.tenantId).toSet
        ownedOrOnboardMember.union(joinedRoster)
      }
    }

  private def anyToJson(v: Any): JsValue = v match {
    case null          => JsNull
    case b: Boolean    => Json.toJson(b)
    case n: Integer    => Json.toJson(n.intValue)
    case l: java.lang.Long => Json.toJson(l.longValue)
    case d: java.lang.Double => Json.toJson(d.doubleValue)
    case other         => Json.toJson(String.valueOf(other))
  }

  private def propsJson(props: Map[String, Any]): JsObject =
    JsObject(props.toSeq.map { case (k, v) => k -> anyToJson(v) }.sortBy(_._1))

  private def rowToNode(row: Map[String, Any]): JsObject =
    JsObject(row.toSeq.map { case (k, v) => k -> anyToJson(v) }.sortBy(_._1))

  def stats(): Action[AnyContent] = authAction.async { req =>
    visibleTenantIds(req.userId).map { tenants =>
      Ok(Json.obj("stats" -> GraphProjectionRepository.statsScoped(tenants)))
    }
  }

  def neighborhood(conceptId: String, depth: Int): Action[AnyContent] = authAction.async { req =>
    if (depth < 1 || depth > 5) {
      Future.successful(BadRequest(Json.obj("errorCode" -> "PARAM_INVALID", "message" -> "depth must be 1..5")))
    } else {
      visibleTenantIds(req.userId).map { tenants =>
        // kn: 对齐（2026-08-30）：投影写侧节点键=kn:<uuid>（DomainEventGraphMappings.kn），读查询必须同前缀——裸 uuid 恒 MISS→404
        val nodeKey = GraphProjectionRepository.knKey(conceptId)
        val params = Map[String, AnyRef]("conceptId" -> nodeKey, "tenants" -> tenants.asJava).asJava
        // BUG-011：根概念不可见 ⇒ MATCH 空转 → 404（不泄漏他租户概念存在性）。
        // v32-r1 实测修正（2026-08-30）：①self/node 一律 properties() 返回——原 `c AS self`/`node: n` 透出
        //   InternalNode 对象，deepToScala 不解 Node → ClassCastException 500（kn: 修复后根首次真正 MATCH 而暴露）；
        // ②邻域语义＝经 ConceptEdge 边节点中转的对端概念（c--e--other，other≠c）：边节点本身带哨兵 tenantId
        //   （Relation 聚合无 tenantId 参数·Rigel 移交项），故不返回 e、只取其对端 Concept 并 strict(other)——
        //   fail-closed：跨租户对端被谓词滤除；e.relationType 作 rel 语义名（替代机械 FROM/TARGET）。
        // ③r 无谓词（D4：关系不携带 tenantId，隔离由端点承载）。
        val cypher =
          "MATCH (c:Concept {conceptId: $conceptId}) WHERE " + GraphProjectionRepository.tenantScopePredStrict("c") +
          " OPTIONAL MATCH (c)--(e:ConceptEdge)--(other:Concept) WHERE other <> c AND " + GraphProjectionRepository.tenantScopePredStrict("other") +
          " RETURN properties(c) AS self, collect(DISTINCT {rel: e.relationType, props: properties(e), node: properties(other)}) AS neighbors"
        Try(GraphProjectionRepository.queryList(cypher, params)) match {
          case Success(rows) =>
            rows.headOption match {
              case Some(row) =>
                val self = Option(row.getOrElse("self", null)).map(_.asInstanceOf[Map[String, Any]]).getOrElse(Map.empty[String, Any])
                val neighbors = row.getOrElse("neighbors", Nil).asInstanceOf[List[Map[String, Any]]]
                val nbJson = neighbors.flatMap { nbRaw =>
                  val nb = Option(nbRaw).getOrElse(Map.empty[String, Any])
                  Option(nb.getOrElse("node", null)).map(_.asInstanceOf[Map[String, Any]]).map { nodeMap =>
                    val props = Option(nb.getOrElse("props", null)).map(_.asInstanceOf[Map[String, Any]]).getOrElse(Map.empty[String, Any])
                    val rel = Option(nb.getOrElse("rel", null)).map(v => String.valueOf(v)).getOrElse("")
                    Json.obj("rel" -> rel, "props" -> propsJson(props), "node" -> rowToNode(nodeMap))
                  }
                }
                Ok(Json.obj("concept" -> rowToNode(self), "neighbors" -> JsArray(nbJson)))
              case None =>
                NotFound(Json.obj("errorCode" -> "VIEW_ITEM_NOT_FOUND", "message" -> s"concept=$conceptId"))
            }
          case Failure(t) =>
            InternalServerError(Json.obj("errorCode" -> "GRAPH_QUERY_FAILED", "message" -> String.valueOf(t.getMessage)))
        }
      }
    }
  }

  def exportGraph(): Action[AnyContent] = authAction.async { req =>
    visibleTenantIds(req.userId).map { tenants =>
      val scopeParams = GraphProjectionRepository.tenantScopeParams(tenants)
      // BUG-011：带 tenantId 属性的节点仅返回 ∈ 可见租户集者；无该属性=全局共享（保守口径见类注释）
      val nodes = GraphProjectionRepository.queryList(
        "MATCH (n) WHERE " + GraphProjectionRepository.tenantScopePredStrict("n") +
        " RETURN labels(n)[0] AS label, properties(n) AS props", scopeParams)
      // 边双端同规则（a/b 端点 strict）。D4（2026-08-30 评审 B-1）：r 谓词移除——关系不携带 tenantId
      // 属性，strict 恒假会滤光全部边；隔离由端点承载（两端点均 strict，无越租户边可见）。
      val edges = GraphProjectionRepository.queryList(
        "MATCH (a)-[r]->(b) WHERE " + GraphProjectionRepository.tenantScopePredStrict("a") +
        " AND " + GraphProjectionRepository.tenantScopePredStrict("b") +
        " RETURN labels(a)[0] AS fromLabel, id(a) AS fromInternal, type(r) AS relType, properties(r) AS relProps, labels(b)[0] AS toLabel, id(b) AS toInternal",
        scopeParams)
      Ok(Json.obj(
        "nodes" -> JsArray(nodes.map(m => Json.obj("label" -> String.valueOf(m.getOrElse("label", "")), "properties" -> propsJson(m.getOrElse("props", Map.empty[String, Any]).asInstanceOf[Map[String, Any]])))),
        "edges" -> JsArray(edges.map(m => Json.obj(
          "fromLabel" -> String.valueOf(m.getOrElse("fromLabel", "")), "relType" -> String.valueOf(m.getOrElse("relType", "")),
          "toLabel" -> String.valueOf(m.getOrElse("toLabel", "")), "props" -> propsJson(m.getOrElse("relProps", Map.empty[String, Any]).asInstanceOf[Map[String, Any]])
        )))
      ))
    }
  }
}
